import type { Handler } from './http.ts';
// Wrong: the route declares id, but this reads code.
export const getLab: Handler<{ id: string }, {}, unknown, { id: string }> = (req, res) => {
  res.status(200).json({ id: req.params.code });
};

export type Req<P = {}, Q = {}, B = unknown> = { params: P; query: Q; body: B };
export type Res<T> = { status(code: number): Res<T>; json(body: T): void };
export type Handler<P = {}, Q = {}, B = unknown, T = unknown> = (req: Req<P, Q, B>, res: Res<T>) => void;

import type { Req, Res } from './http.ts';
export function fakeRes<T>(sink: { body?: T; code?: number }): Res<T> { return { status(code) { sink.code = code; return this; }, json(body) { sink.body = body; } }; }
export function fakeReq<P, Q, B>(parts: { params?: P; query?: Q; body?: B }): Req<P, Q, B> { return { params: (parts.params ?? {}) as P, query: (parts.query ?? {}) as Q, body: parts.body as B }; }

import { getLab } from '../src/handler.ts';
import { fakeReq, fakeRes } from '../src/run.ts';
const sink: { body?: { id: string } } = {};
getLab(fakeReq({ params: { id: 'BE-201' } }), fakeRes(sink));
export { sink };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getLab } from '../src/handler.ts';
import { fakeReq, fakeRes } from '../src/run.ts';
test('getLab', () => { const s: { body?: { id: string } } = {}; getLab(fakeReq({ params: { id: 'BE-201' } }), fakeRes(s)); assert.equal(s.body?.id, 'BE-201'); });

